27	export function fmtDur(s: number | null | undefined): string {
28	  if (s == null) return "—";
29	  if (s < 60) return `${s.toFixed(s < 10 ? 1 : 0)}s`;
30	  const m = Math.floor(s / 60);
31	  return `${m}m ${String(Math.round(s % 60)).padStart(2, "0")}s`;
32	}
