56	/** Latest run per repo (the list is newest first). */
57	export function latestPerRepo(runs: RunSummary[]): RunSummary[] {
58	  const seen = new Set<string>();
59	  const out: RunSummary[] = [];
60	  for (const r of runs) {
61	    const key = `${r.repo}|${r.path}`;
62	    if (!r.repo || r.status === "checking" || seen.has(key)) continue;
63	    seen.add(key);
64	    out.push(r);
65	  }
66	  return out;
67	}
