69	export type ReplayEvent =
70	  | { kind: "step"; side: "agent" | "verifier"; step: Step }
71	  | { kind: "model"; call: ModelCall };
72	
73	/** Recorded steps in order, with each model call placed where it started. */
74	export function buildEvents(result: RunResult): ReplayEvent[] {
75	  const calls = [...(result.model_calls ?? [])].sort((a, b) => (a.started ?? 0) - (b.started ?? 0));
76	  const events: ReplayEvent[] = [];
77	  let ci = 0;
78	  const flushCalls = (before: number | undefined) => {
79	    while (ci < calls.length && (before === undefined || (calls[ci].started ?? 0) < before)) {
80	      events.push({ kind: "model", call: calls[ci++] });
81	    }
82	  };
83	  for (const step of result.agent?.steps ?? []) {
84	    if (step.started !== undefined) flushCalls(step.started);
85	    events.push({ kind: "step", side: "agent", step });
86	  }
87	  flushCalls(undefined);
88	  for (const step of result.verifier?.steps ?? []) events.push({ kind: "step", side: "verifier", step });
89	  return events;
90	}
