92	/** The agent's plan as a task list: each stage it ran, its repair attempts, then the verifier. */
93	export function buildTasks(result: RunResult): AITask[] {
94	  const steps = result.agent?.steps ?? [];
95	  const order: string[] = [];
96	  const last = new Map<string, Step>();
97	  for (const s of steps) {
98	    if (!last.has(s.name)) order.push(s.name);
99	    last.set(s.name, s);
100	  }
101	  const attempts = result.agent?.attempts ?? [];
102	  const tasks: AITask[] = order.map((name, i) => {
103	    const s = last.get(name)!;
104	    const runs = steps.filter((x) => x.name === name).length;
105	    return {
106	      id: `stage-${i}`,
107	      label: STAGE_LABEL[name] ?? name,
108	      status: stepOk(s) ? "done" : "failed",
109	      note: runs > 1 ? `${runs} runs` : fmtDur(s.duration_s),
110	    };
111	  });
112	  // Repairs hang off the first stage that ever failed, even if a later attempt got it through.
113	  const firstFailed = steps.find((s) => !stepOk(s));
114	  const failedStage = firstFailed ? tasks[order.indexOf(firstFailed.name)] : undefined;
115	  const repairs: AITask[] = attempts.map((a, i) => ({
116	    id: `fix-${i}`,
117	    label: `Repair ${i + 1}: ${a.kind ?? "fix"} in ${(a.files ?? []).join(", ") || "—"}`,
118	    status: a.status === "needs_approval" ? "pending" : a.result === "passed" ? "done" : "failed",
119	    note: a.status === "needs_approval" ? "needs approval" : undefined,
120	  }));
121	  if (repairs.length) {
122	    const target = failedStage ?? tasks[tasks.length - 1];
123	    if (target) target.children = repairs;
124	    else tasks.push(...repairs);
125	  }
126	  const v = result.verifier?.steps ?? [];
127	  tasks.push({
128	    id: "verify",
129	    label: "Rebuild in a separate clean container",
130	    status: v.length === 0 ? "pending" : v.every(stepOk) ? "done" : "failed",
131	    note: v.length === 0 ? "not reached" : fmtDur(v.reduce((a, s) => a + (s.duration_s ?? 0), 0)),
132	  });
133	  return tasks;
134	}
