147	/** One AI Diff block per file in a unified patch. */
148	export function parsePatch(patch: string): { title: string; lines: AIDiffLine[] }[] {
149	  const files: { title: string; lines: AIDiffLine[] }[] = [];
150	  let cur: { title: string; lines: AIDiffLine[] } | null = null;
151	  for (const raw of patch.replace(/\n$/, "").split("\n")) {
152	    if (raw.startsWith("diff --git ")) {
153	      cur = { title: raw.replace(/^diff --git a\/(.*) b\/.*$/, "$1"), lines: [] };
154	      files.push(cur);
155	    } else if (!cur || /^(index |--- |\+\+\+ |new file|deleted file|old mode|new mode|similarity|rename )/.test(raw)) {
156	      continue;
157	    } else if (raw.startsWith("@@")) {
158	      cur.lines.push({ kind: "context", content: raw });
159	    } else if (raw.startsWith("+")) {
160	      cur.lines.push({ kind: "added", content: raw.slice(1) });
161	    } else if (raw.startsWith("-")) {
162	      cur.lines.push({ kind: "removed", content: raw.slice(1) });
163	    } else if (raw.length || cur.lines.length) {
164	      cur.lines.push({ kind: "context", content: raw.slice(1) });
165	    }
166	  }
167	  return files.filter((f) => f.lines.length);
168	}
