115	type Async<T> = { data: T | null; error: string | null; loading: boolean };
116	
117	function useFetch<T>(url: string | null): Async<T> {
118	  const [state, setState] = useState<Async<T>>({ data: null, error: null, loading: url !== null });
119	  useEffect(() => {
120	    if (url === null) {
121	      setState({ data: null, error: null, loading: false });
122	      return;
123	    }
124	    const ctl = new AbortController();
125	    setState({ data: null, error: null, loading: true });
126	    fetch(url, { signal: ctl.signal })
127	      .then(async (r) => {
128	        if (!r.ok) throw new Error(r.status === 404 ? "Not found" : `Request failed (${r.status})`);
129	        return (await r.json()) as T;
130	      })
131	      .then((data) => setState({ data, error: null, loading: false }))
132	      .catch((e: unknown) => {
133	        if ((e as Error).name !== "AbortError") setState({ data: null, error: (e as Error).message, loading: false });
134	      });
135	    return () => ctl.abort();
136	  }, [url]);
137	  return state;
138	}
